import { createContext, useContext, useMemo, useState } from 'react';

const StoreContext = createContext(null);

export function StoreProvider({ children }) {
  const [cart, setCart] = useState([]);
  const [wishlist, setWishlist] = useState([]);
  const [authOpen, setAuthOpen] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [compareOpen, setCompareOpen] = useState(false);
  const [toast, setToast] = useState(null);
  const [darkMode, setDarkMode] = useState(false);

  const showToast = (message, type = 'info') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  const addToCart = (product, quantity = 1) => {
    setCart((items) => {
      const id = product.id || product.productId;
      const existing = items.find((item) => (item.id || item.productId) === id);
      if (existing) {
        return items.map((item) =>
          (item.id || item.productId) === id ? { ...item, quantity: item.quantity + quantity } : item
        );
      }
      return [...items, { ...product, id, quantity }];
    });
    showToast(`${product.title || product.name} added to cart`, 'success');
  };

  const removeFromCart = (productId) => {
    setCart((items) => items.filter((item) => (item.id || item.productId) !== productId));
    showToast('Item removed from cart', 'info');
  };

  const updateQuantity = (productId, quantity) => {
    if (quantity <= 0) return removeFromCart(productId);
    setCart((items) => items.map((item) => ((item.id || item.productId) === productId ? { ...item, quantity } : item)));
  };

  const toggleWishlist = (product) => {
    const id = product.id || product.productId;
    setWishlist((items) => {
      const exists = items.some((item) => (item.id || item.productId) === id);
      if (exists) {
        showToast('Removed from wishlist', 'info');
        return items.filter((item) => (item.id || item.productId) !== id);
      }
      showToast('Added to wishlist', 'success');
      return [...items, { ...product, id }];
    });
  };

  const cartSubtotal = useMemo(
    () => cart.reduce((sum, item) => sum + (Number(item.price) || 0) * item.quantity, 0),
    [cart]
  );
  const discount = useMemo(() => Math.round(cartSubtotal * 0.05), [cartSubtotal]);
  const tax = useMemo(() => Math.round((cartSubtotal - discount) * 0.08), [cartSubtotal, discount]);
  const delivery = cartSubtotal > 0 && cartSubtotal < 500 ? 25 : 0;
  const cartTotal = Math.max(0, cartSubtotal - discount + tax + delivery);

  const value = {
    cart,
    wishlist,
    authOpen,
    selectedProduct,
    compareOpen,
    toast,
    darkMode,
    cartSubtotal,
    discount,
    tax,
    delivery,
    cartTotal,
    cartCount: cart.reduce((sum, item) => sum + item.quantity, 0),
    openAuth: () => setAuthOpen(true),
    closeAuth: () => setAuthOpen(false),
    openProduct: setSelectedProduct,
    closeProduct: () => setSelectedProduct(null),
    openCompare: () => setCompareOpen(true),
    closeCompare: () => setCompareOpen(false),
    addToCart,
    removeFromCart,
    updateQuantity,
    clearCart: () => { setCart([]); showToast('Cart cleared', 'info'); },
    toggleWishlist,
    showToast,
    toggleTheme: () => setDarkMode((value) => !value),
  };

  return <StoreContext.Provider value={value}>{children}</StoreContext.Provider>;
}

export function useStore() {
  const context = useContext(StoreContext);
  if (!context) throw new Error('useStore must be used inside StoreProvider');
  return context;
}
